{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is live edge furniture?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Live edge furniture preserves the natural outer edge of the tree in the finished piece. Instead of cutting the wood into a uniform rectangle, the organic curves, bark line, and raw character of the slab are kept intact. The result is a one-of-a-kind piece that showcases the tree's natural beauty — knots, grain patterns, and all."
        }
      },
      {
        "@type": "Question",
        "name": "What types of wood do you use?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We specialize in Texas hardwoods: Black Walnut (rich dark tones, dramatic grain), Pecan (warm golden hues, versatile character), Mesquite (extremely hard, wild grain patterns unique to Texas), White Oak (light, strong, classic look), and Cedar (aromatic, warm reddish tones). We also work with other species on request."
        }
      },
      {
        "@type": "Question",
        "name": "How much does a custom live edge table cost?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Pricing depends on the wood species, slab size, design complexity, and finish. Coffee tables typically start around $800-$1,500. Dining tables range from $1,800-$5,000+. Desks run $1,500-$3,000. Refinishing projects start around $300. We provide detailed, no-obligation quotes for every project."
        }
      },
      {
        "@type": "Question",
        "name": "How long does a custom piece take to build?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Most custom pieces take 4-8 weeks from approval to delivery. Larger or more complex projects (like epoxy river tables or commercial installations) may take 8-12 weeks. Refinishing projects are typically 2-4 weeks. We'll give you a clear timeline when we provide your quote."
        }
      },
      {
        "@type": "Question",
        "name": "Do you deliver? How far?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, we deliver throughout the San Antonio metro area and surrounding communities including Alamo Heights, Stone Oak, The Dominion, Boerne, New Braunfels, Helotes, and Bulverde. Delivery within San Antonio is typically included in the price. We can arrange delivery to other Texas locations for an additional fee."
        }
      },
      {
        "@type": "Question",
        "name": "How do I care for and maintain my live edge piece?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Daily care is simple: wipe with a soft, damp cloth. Avoid harsh chemicals. Use coasters for hot or wet items. Depending on your finish, we recommend reapplying a maintenance coat of oil or wax every 6-12 months. We'll provide specific care instructions with every piece we deliver."
        }
      }
    ]
  }

